// Des: Tests for the gap report: drift, unknown controls, coverage
// Flo: map fake pages > compute > assert counts and rows; rename a label to simulate Facebook drift > report it with exit class Drift
// I/O: real local Chrome (skipped when absent) + mock site > pass or fail (no leaks)
// Run: zig build test -Dfile=ru-gaps-main-test.zig
// ===================================================================
const std = @import("std"); const rigz = @import("te-rigz-brow.zig"); const crwl = @import("ru-map-crwl.zig"); const gaps = @import("ru-gaps-main.zig"); const task = @import("ru-task-runn.zig"); const cfgz = @import("cf-conf-load.zig");
fn ctxOf(rig: *rigz.Rig) !task.Ctx { rig.conf.noti_chai_orde = &.{"file"}; var cx = rig.ctx(.read); cx.statd = try rig.absOf("stat"); return cx; }
fn has(rig: *rigz.Rig, needle: []const u8) bool { return std.mem.find(u8, rig.sink.items, needle) != null; }
fn mapDir(cx: *task.Ctx) ![]const u8 { const day = try crwl.dayStr(cx.aren, task.nowMs(cx)); return std.fs.path.join(cx.aren, &.{ cx.statd, "map", day }); }
fn seed(rig: *rigz.Rig) !task.Ctx { rig.conf.map_seed_list = &.{ "/settings/privacy", "/saved", "/accountscenter/password_and_security", "/settings/blocking" }; rig.conf.map_deep_maxx = 0; var cx = try ctxOf(rig); try std.testing.expectEqual(@as(u32, 4), try crwl.mapRun(&cx)); return cx; }
test "without a map the report says so and fails with BadUsage" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); var cx = try ctxOf(&rig); try std.testing.expectError(error.BadUsage, gaps.gapsRun(&cx, "", false)); try std.testing.expect(has(&rig, "run fb-face-webs map first")); }
test "a map that matches the labels has no drift, and lists controls no label knows" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); var cx = try seed(&rig); const rep = try gaps.compute(&cx, try mapDir(&cx)); try std.testing.expectEqual(@as(usize, 4), rep.pages); if (rep.drift.len > 0) { for (rep.drift) |ln| std.debug.print("drift: {s}\n", .{ln}); } try std.testing.expectEqual(@as(usize, 0), rep.drift.len); var found = false; for (rep.unused) |ln| { if (std.mem.find(u8, ln, "Ann Lee") != null) found = true; } try std.testing.expect(found); try std.testing.expect(rep.unmapped > 0); try gaps.gapsRun(&cx, "", false); try std.testing.expect(has(&rig, "gaps: 4 pages mapped")); try std.testing.expect(has(&rig, "NEW   /settings/blocking | button | Ann Lee")); }
test "a renamed button is reported as DRIFT and gapsRun fails with Drift" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); var cx = try seed(&rig); var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const ovr = try cfgz.confParse(aren.allocator(), "{\"labl_over\":{\"sett_audi\":[\"Nonexistent label\"]}}"); cx.conf.labl_over = ovr.labl_over; const rep = try gaps.compute(&cx, try mapDir(&cx)); try std.testing.expect(rep.drift.len >= 1); var found = false; for (rep.drift) |ln| { if (std.mem.startsWith(u8, ln, "sett-audience-default:")) found = true; } try std.testing.expect(found); try std.testing.expectError(error.Drift, gaps.gapsRun(&cx, "", false)); try std.testing.expect(has(&rig, "DRIFT sett-audience-default")); }
test "the coverage matrix lists every job with area, class, cap kind and page key" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); var cx = try ctxOf(&rig); try gaps.gapsRun(&cx, "matrix", false); try std.testing.expect(has(&rig, "acct-login | acct | H | acct | path_logi_main")); try std.testing.expect(has(&rig, "post-delete | core | G | post | url")); try std.testing.expect(has(&rig, "sett-audience-default | sett | A | acct | path_sett_priv")); try std.testing.expect(has(&rig, "mone-ads-create | mone | H | mone | pbiz_adsz_main")); try std.testing.expect(has(&rig, "post | core | A | post | code")); }
